// Prepare lead data for AI generation
const record = $input.item.json;
const f = record.fields || {};

const firstName = f.first_name || f.name?.split(' ')[0] || f.ig_handle?.split('_')[0] || 'there';

return [{
  json: {
    record_id: record.id,
    ig_handle: f.ig_handle || '',
    first_name: firstName,
    full_name: f.name || firstName,
    niche: f.niche || 'creator',
    score: f.score || 0,
    outreach_priority: f.outreach_priority || 'medium',
    estimated_revenue_band: f.estimated_revenue_band || 'unknown',
    personalization_hook: f.personalization_hook || 'your content',
    linkedin_url: f.linkedin_url || '',
    email: f.email || '',
    ig_followers: f.ig_followers || 0
  }
}];

