// Combine all AI drafts
const leadData = $('Prep Lead Data').item.json;
const igDmResp = $('Claude — Generate IG DM').item.json;
const liNoteResp = $('Claude — Generate LinkedIn Note').item.json;
const liFollowupResp = $('Claude — Generate LinkedIn Followup').item.json;

const igDm = igDmResp?.content?.[0]?.text?.trim() || 'Could not generate IG DM';
const liNote = liNoteResp?.content?.[0]?.text?.trim() || 'Could not generate LinkedIn note';
const liFollowup = liFollowupResp?.content?.[0]?.text?.trim() || 'Could not generate LinkedIn followup';

return [{
  json: {
    ...leadData,
    ig_dm_draft: igDm,
    linkedin_note: liNote,
    linkedin_followup: liFollowup
  }
}];

